\begin{tikzpicture}
\begin{axis}[
    width=0.72\textwidth,
    height=0.46\textwidth,
    xmin=-3.2, xmax=5.2,
    ymin=-0.5, ymax=8,
    axis lines=left,
    xlabel={\(x\)},
    ylabel={\(y\)},
    xtick={-2,0,2,4},
    ytick={0,3},
    grid=both,
    grid style={line width=.1pt, draw=gray!25},
    legend style={at={(0.98,0.98)},anchor=north east,legend columns=1,font=\small}
]
\addplot[thick, domain=-2.5:2.5, samples=80] {x^2};
\addlegendentry{\(f(x)=x^2\)}
\addplot[thick, dashed, domain=-2.5:2.5, samples=80] {x^2+3};
\addlegendentry{\(f(x)+3\)}
\addplot[thick, dotted, domain=-0.5:4.5, samples=80] {(x-2)^2};
\addlegendentry{\(f(x-2)\)}
\end{axis}
\end{tikzpicture}

p.me:
\begin{array}{c|c|c}
\textbf{new function} \amp \textbf{point movement} \amp \textbf{graph effect}\\
\hline
f(x)+k \amp (a,f(a))\mapsto(a,f(a)+k) \amp \text{vertical shift}\\
f(x-c) \amp (a,f(a))\mapsto(a+c,f(a)) \amp \text{horizontal shift}\\
Af(x) \amp (a,f(a))\mapsto(a,Af(a)) \amp \text{vertical scaling}\\
f(Bx),\ B>0 \amp (a,f(a))\mapsto(a/B,f(a)) \amp \text{horizontal scaling}\\
-f(x) \amp (a,f(a))\mapsto(a,-f(a)) \amp \text{reflection across \(x\)-axis}\\
f(-x) \amp (a,f(a))\mapsto(-a,f(a)) \amp \text{reflection across \(y\)-axis}
\end{array}

